<?php
$inventory=database()->query('SELECT p.*,COALESCE(SUM(sp.quantity),0) AS used_quantity,COUNT(DISTINCT sp.service_id) AS service_count FROM parts_catalog p LEFT JOIN service_parts sp ON sp.part_id=p.id GROUP BY p.id ORDER BY p.name')->fetchAll();
$popular=database()->query('SELECT p.id,p.name,p.category,p.stock_qty,SUM(sp.quantity) AS used_quantity,COUNT(DISTINCT sp.service_id) AS service_count FROM parts_catalog p JOIN service_parts sp ON sp.part_id=p.id GROUP BY p.id,p.name,p.category,p.stock_qty ORDER BY used_quantity DESC,p.name LIMIT 10')->fetchAll();
$missing=array_values(array_filter($inventory,fn($part)=>(int)$part['stock_qty']===0));
$totalUnits=array_sum(array_map(fn($part)=>(int)$part['stock_qty'],$inventory));
$lowCount=count(array_filter($inventory,fn($part)=>(int)$part['stock_qty']<=(int)$part['min_stock']));
?>
<div class="page-heading"><div><span class="eyebrow">DEPOJA E SERVISIT</span><h1>Stoku i pjesëve</h1><p>Shiko çka ka në depo, cilat pjesë kërkohen më shpesh dhe çka duhet rimbushur.</p></div><a class="btn primary" href="?page=management">＋ Regjistro blerje</a></div>
<section class="stat-grid"><article class="stat-card"><div class="stat-top"><span>Lloje pjesësh</span><span class="stat-icon blue">▤</span></div><strong><?=count($inventory)?></strong><small>Artikuj në katalog</small></article><article class="stat-card"><div class="stat-top"><span>Copë në stok</span><span class="stat-icon green">▣</span></div><strong><?=number_format($totalUnits)?></strong><small>Sasia e përgjithshme në depo</small></article><article class="stat-card"><div class="stat-top"><span>Stok i ulët</span><span class="stat-icon amber">!</span></div><strong><?=$lowCount?></strong><small>Në ose nën pragun minimal</small></article><article class="stat-card"><div class="stat-top"><span>Pa stok</span><span class="stat-icon violet">↗</span></div><strong><?=count($missing)?></strong><small>Pjesë që mungojnë</small></article></section>

<div class="inventory-insights-grid">
<section class="panel table-panel inventory-insight-panel"><div class="panel-head"><div><span class="eyebrow">KËRKESA NGA SERVISET</span><h2>Pjesët që përdoren më shumë</h2><p>Sipas copave regjistruara në punët e servisit</p></div><span class="inventory-section-icon">↗</span></div><?php if($popular):?><div class="table-wrap"><table><thead><tr><th>Pjesa</th><th>Kategoria</th><th>Copë të përdorura</th><th>Servise</th><th>Stoku tani</th></tr></thead><tbody><?php foreach($popular as $part):?><tr><td><b><?=h($part['name'])?></b></td><td><?=h($part['category'])?></td><td><span class="inventory-usage-count"><?=number_format((int)$part['used_quantity'])?> copë</span></td><td><?=number_format((int)$part['service_count'])?></td><td><?=$part['stock_qty']?><?php if((int)$part['stock_qty']===0):?> <span class="status-pill overdue">Mungon</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="inventory-empty-state"><span>▤</span><b>S’ka ende të dhëna përdorimi</b><p>Pjesët shfaqen këtu pasi mekaniku t’i regjistrojë te punët e servisit.</p></div><?php endif;?></section>

<section class="panel table-panel inventory-insight-panel inventory-missing-panel"><div class="panel-head"><div><span class="eyebrow">DUHET RIBLERE</span><h2>Pjesët që kanë mbaruar</h2><p><?=count($missing)?> artikuj me stok zero</p></div><span class="inventory-section-icon warning">!</span></div><?php if($missing):?><div class="inventory-missing-list"><?php foreach($missing as $part):?><article><div><b><?=h($part['name'])?></b><small><?=h($part['category'])?> · Furnitori: <?=h($part['supplier']?:'pa furnitor')?></small></div><span>0 copë</span></article><?php endforeach;?></div><a class="text-link inventory-order-link" href="?page=management">Regjistro blerje për t’i rimbushur →</a><?php else:?><div class="inventory-empty-state success"><span>✓</span><b>Nuk mungon asnjë pjesë</b><p>Të gjitha pjesët e katalogut kanë stok.</p></div><?php endif;?></section>
</div>

<section class="panel table-panel inventory-all-panel"><div class="panel-head"><div><span class="eyebrow">PASQYRA E DEPOTSË</span><h2>Të gjitha pjesët në stok</h2><p>Lista e plotë me sasinë, furnitorin dhe pragun e rimbushjes</p></div><a class="text-link" href="?page=management">Menaxho katalogun →</a></div><div class="table-wrap"><table><thead><tr><th>Pjesa</th><th>Kategoria / kodi</th><th>Furnitori</th><th>Çmimi për copë</th><th>Sasia</th><th>Pragu minimal</th><th>Gjendja</th></tr></thead><tbody><?php foreach($inventory as $part):$qty=(int)$part['stock_qty'];$min=(int)$part['min_stock'];?><tr><td><b><?=h($part['name'])?></b></td><td><?=h($part['category'])?><small class="table-sub"><?=h($part['sku']?:'Pa kod')?></small></td><td><?=h($part['supplier']?:'—')?></td><td>€<?=number_format((float)$part['unit_cost'],2)?></td><td><b><?=$qty?></b> copë</td><td><?=$min?> copë</td><td><?php if($qty===0):?><span class="inventory-state missing">Mungon</span><?php elseif($qty<=$min):?><span class="inventory-state low">Stok i ulët</span><?php else:?><span class="inventory-state available">Në stok</span><?php endif;?></td></tr><?php endforeach;?><?php if(!$inventory):?><tr><td colspan="7"><div class="inventory-empty-state"><span>▤</span><b>Katalogu është bosh</b><p>Shto pjesët dhe sasinë fillestare në menaxhimin e servisit.</p></div></td></tr><?php endif;?></tbody></table></div></section>
